VALUES (11976, 'tt0089469', NULL, 'Legend', 'Legend', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/6n3PQSYpZRK5YPk2w8JEwED7AZk.jpg', 'https://image.tmdb.org/t/p/original/3g8rLMw0SbA0h2GHiOCBoqFTXVq.jpg', 'Set in a timeless mythical forest inhabited by fairies, goblins, unicorns and mortals, this fantastic story follows a mystical forest dweller, chosen by fate, to undertake a heroic quest. He must save the beautiful Princess  Lili and defeat the demonic Lord of Darkness, or the world will be plunged into a never-ending ice age.', NULL, NULL, 6.4651, 6.253, 0, 8.80785365853658532e+01, '2026-07-15 12:01:52', '2026-10-20 23:15:30')
