VALUES (879, 'tt0102057', NULL, 'Hook', 'Hook', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/a6rB1lGXoGms7gWxRfJneQmAjNV.jpg', 'https://image.tmdb.org/t/p/original/39OxcFZjX4uc6vYzexUh5qXghxE.jpg', 'The boy who wasn''t supposed to grow up—Peter Pan—does just that, becoming a soulless corporate lawyer whose workaholism could cost him his wife and kids. During his trip to see Granny Wendy in London, the vengeful Capt. Hook kidnaps Peter''s kids and forces Peter to return to Neverland.', NULL, NULL, 9.4727, 6.846, 0, 5.23265957446808442e+01, '2026-07-15 12:01:52', '2026-10-20 23:15:30')
