VALUES (28032, 'tt0111419', NULL, 'Thumbelina', 'Thumbelina', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/eBvSSfwAKgcjF4eyaeNSzTCpfaF.jpg', 'https://image.tmdb.org/t/p/original/jhxmxSNBNCAKtHeJnJhWpkOOI7d.jpg', 'Born of a flower and growing to only a couple of inches tall, poor Thumbelina is worried she''ll never meet someone her own size, until she happens to catch the eye of Prince Cornelius of the Fairies. Just as soon as she finds love, however, it''s torn away when she''s kidnapped by Ms. Toad. Now Thumbelina has to escape Ms. Toad''s grasp and search for Prince Cornelius. Luckily, there''s a whole city of animals willing to help.', NULL, NULL, 6.3494, 6.467, 0, 25.857, '2026-07-15 12:01:52', '2026-10-20 23:15:30')
